    from invtrack.cli import build_parser
    from invtrack.db import get_connection, init_db
    from invtrack.handlers import (
        handle_init,
        handle_item_add,
        handle_item_get,
        handle_item_list,
        handle_item_adjust,
        handle_item_delete,
        handle_report_low,
        handle_report_value,
    )

    parser = build_parser()
    args = parser.parse_args()

    if not hasattr(args, "db"):
        parser.error("--db is required before subcommand")

    conn = get_connection(args.db)

    if args.command == "init":
        code, msg = handle_init(conn)
    elif args.command == "item":
        if args.item_command == "add":
            code, msg = handle_item_add(conn, args.sku, args.name, args.qty, args.price)
        elif args.item_command == "get":
            code, msg = handle_item_get(conn, args.sku)
        elif args.item_command == "list":
            code, msg = handle_item_list(conn, getattr(args, "format", "table"))
        elif args.item_command == "adjust":
            code, msg = handle_item_adjust(conn, args.sku, args.delta)
        elif args.item_command == "delete":
            code, msg = handle_item_delete(conn, args.sku)
        else:
            parser.error(f"Unknown item subcommand: {args.item_command}")
    elif args.command == "report":
        if args.report_command == "low":
            code, msg = handle_report_low(conn, args.threshold)
        elif args.report_command == "value":
            code, msg = handle_report_value(conn)
        else:
            parser.error(f"Unknown report subcommand: {args.report_command}")
    else:
        parser.error(f"Unknown command: {args.command}")

    conn.close()

    if msg is not None:
        print(msg)

    import sys

    sys.exit(code)
